def blob(path):
    return subprocess.check_output(['git', 'hash-object', path], text=True).strip()
def verify():
    for path, expected in EXPECTED.items():
        actual = blob(path)
        if actual != expected: raise RuntimeError(f'Unexpected prepared source: {path}: {actual} != {expected}')
if os.environ.get('GITHUB_REPOSITORY') != REPO or os.environ.get('GITHUB_REF') != WORKBENCH:
    raise RuntimeError('This source tool runs only in the isolated approved workbench branch.')
if sys.argv[1] == 'apply':
    for path, (before, edits) in EDIT_SPEC.items():
        if blob(path) != before: raise RuntimeError('Refusing different source base: ' + path)
        lines = Path(path).read_text().splitlines(keepends=True)
        for start, end, value in reversed(edits): lines[start:end] = value.splitlines(keepends=True)
        Path(path).write_text(''.join(lines))
    verify()
    subprocess.run(['git','diff','--check'], check=True)
    print('Verified all 23 prepared source blobs; no runtime transform or production operation.')
elif sys.argv[1] == 'propose':
    verify()
    def api(path, data=None):
        request=urllib.request.Request('https://api.github.com/repos/'+REPO+path,
            data=None if data is None else json.dumps(data).encode(),
            headers={'Authorization':'Bearer '+os.environ['GH_TOKEN'],'Accept':'application/vnd.github+json','Content-Type':'application/json'},
            method='GET' if data is None else 'POST')
        with urllib.request.urlopen(request, timeout=60) as response: return json.load(response)
    if api('/git/ref/heads/feature/projects-canonical-integration')['object']['sha'] != BASE:
        raise RuntimeError('Feature branch advanced. Do not overwrite unrelated work.')
    base_tree=api('/git/commits/'+BASE)['tree']['sha']
    entries=[]
    for path, expected in EXPECTED.items():
        made=api('/git/blobs',{'content':Path(path).read_text(),'encoding':'utf-8'})
        if made['sha'] != expected: raise RuntimeError('Blob publication mismatch: '+path)
        entries.append({'path':path,'mode':'100644','type':'blob','sha':expected})
    entries.append({'path':'.github/workflows/projects-source-review-checkpoint.yml','mode':'100644','type':'blob','sha':None})
    tree=api('/git/trees',{'base_tree':base_tree,'tree':entries})
    commit=api('/git/commits',{'message':'feat(projects): add cumulative scope reviews, shared templates, lifecycle and safe write pause\n\nReuse canonical Field evidence and the established Project registry transaction, permissions, versions and audit. Keep budgets advisory and preserve exact-request recovery during a pause. Add isolated unit, browser and emulator acceptance. No production activation, migration, main merge or finance/time fabrication.', 'tree':tree['sha'],'parents':[BASE]})
    result={'proposedCommit':commit['sha'],'base':BASE,'tree':tree['sha'],'sourceBlobs':EXPECTED,'branchMoved':False,'productionAccessed':False}
    Path('reviewed-proposed-commit.json').write_text(json.dumps(result,indent=2))
    print('PROPOSED_COMMIT='+commit['sha'])
else:
    raise RuntimeError('Unsupported source-workbench operation.')
